#!/usr/bin/env node
// Synchronise documentation from the code and knowledge repositories into
// src/content/docs/docs/. The page list is scripts/docs-manifest.json (an
// allowlist: the per-gemeente review sheets are deliberately not synced).
//
//   node scripts/sync-docs.mjs
//
// Sources: a shallow clone of each public repository into .cache/sync/, or a
// local checkout given by SW_CODE_DIR / SW_KNOWLEDGE_DIR (handy when editing
// docs). SW_REF overrides the branch. Generated files are git-ignored.
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

if (process.env.SW_SYNC_SKIP) {
  console.log('SW_SYNC_SKIP set: not syncing docs');
  process.exit(0);
}

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'src/content/docs/docs');
const ORG = 'straatwijsheid';
const manifest = JSON.parse(fs.readFileSync(path.join(ROOT, 'scripts/docs-manifest.json'), 'utf8'));
const REF = process.env.SW_REF || manifest.ref;

const git = (cwd, ...args) => execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'inherit'] }).trim();

function acquire(key) {
  const { name, env } = manifest.repos[key];
  let dir = process.env[env];
  if (dir) {
    console.log(`${name}: using local checkout ${dir}`);
  } else {
    dir = path.join(ROOT, '.cache/sync', name);
    const url = `https://github.com/${ORG}/${name}.git`;
    if (fs.existsSync(path.join(dir, '.git'))) {
      git(dir, 'fetch', '--depth', '1', 'origin', REF);
      git(dir, 'reset', '--hard', 'FETCH_HEAD');
    } else {
      fs.mkdirSync(path.dirname(dir), { recursive: true });
      git(ROOT, 'clone', '--depth', '1', '--branch', REF, url, dir);
    }
  }
  return { dir, name, sha: git(dir, 'rev-parse', '--short', 'HEAD') };
}

const repos = Object.fromEntries(Object.keys(manifest.repos).map((k) => [k, acquire(k)]));
const bySource = new Map(manifest.pages.map((p) => [`${p.repo}:${p.path}`, p]));
const ghUrl = (kind, repo, p) => `https://github.com/${ORG}/${repos[repo].name}/${kind}/${REF}/${p}`;

function rewriteUrl(url, repo, srcPath) {
  if (/^[a-z][a-z0-9+.-]*:/i.test(url) || url.startsWith('#') || url.startsWith('/')) return url;
  const [target, hash = ''] = url.split(/(?=#)/);
  const resolved = path.posix.normalize(path.posix.join(path.posix.dirname(srcPath), target));
  if (resolved.startsWith('..')) return url;
  const page = bySource.get(`${repo}:${resolved}`);
  if (page) return `/docs/${page.slug}/${hash}`;
  const isDir = target.endsWith('/') || !path.posix.extname(resolved);
  return ghUrl(isDir ? 'tree' : 'blob', repo, resolved) + hash;
}

// One pass: fenced code is left alone; inline links and reference definitions are rewritten.
const TOKEN = /(^(?:```|~~~)[^\n]*\n[\s\S]*?^(?:```|~~~)[ \t]*$)|(\]\()([^)\s]+)((?:\s+"[^"]*")?\))|(^\[[^\]\n]+\]:\s*)(\S+)/gm;
function rewriteLinks(body, repo, srcPath) {
  return body.replace(TOKEN, (m, fence, open, url, rest, refOpen, refUrl) => {
    if (fence) return m;
    if (open) return `${open}${rewriteUrl(url, repo, srcPath)}${rest}`;
    return `${refOpen}${rewriteUrl(refUrl, repo, srcPath)}`;
  });
}

fs.mkdirSync(OUT, { recursive: true });
for (const f of fs.readdirSync(OUT)) {
  if (f !== 'index.md' && f !== '.gitignore') fs.rmSync(path.join(OUT, f), { recursive: true });
}

for (const page of manifest.pages) {
  const { dir, sha } = repos[page.repo];
  const file = path.join(dir, page.path);
  if (!fs.existsSync(file)) throw new Error(`${page.repo}/${page.path} not found (is it renamed? update scripts/docs-manifest.json)`);
  let body = fs.readFileSync(file, 'utf8').replace(/^﻿/, '');
  body = body.replace(/^\s*# .*\n+/, ''); // the page title comes from the frontmatter
  body = rewriteLinks(body, page.repo, page.path);
  const src = `${repos[page.repo].name}/${page.path}`;
  const front = [
    '---',
    `title: ${JSON.stringify(page.title)}`,
    `description: ${JSON.stringify(page.description)}`,
    `editUrl: ${ghUrl('edit', page.repo, page.path)}`,
    'sidebar:',
    `  order: ${page.order}`,
    '---',
    '',
    `{/* Generated by scripts/sync-docs.mjs from ${src} at ${sha}. Do not edit here. */}`,
    '',
  ].join('\n').replace(/\{\/\*(.*)\*\/\}/, '<!-- $1 -->');
  const note = `\n\n---\n\n*Synced from [${src}](${ghUrl('blob', page.repo, page.path)}) at \`${sha}\`. To change this page, edit it there.*\n`;
  fs.writeFileSync(path.join(OUT, `${page.slug}.md`), front + body.trimEnd() + note);
}
console.log(`synced ${manifest.pages.length} pages (${Object.values(repos).map((r) => `${r.name}@${r.sha}`).join(', ')})`);
